import React, { useState, useEffect } from 'react';
import api from '../../services/api';

const MenuPage = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    name: '', description: '', history: '', ingredients: '',
    price: '', cost: '', category_id: '', preparation_time_min: 15,
    image_url: '', model_3d_url: '', is_available: true,
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    const menuRes = await api.get('/menu/SUC-001');
    const cats = menuRes.data.data.categories;
    setCategories(cats);
    const allProducts = cats.flatMap(c => c.products.map(p => ({ ...p, categoryName: c.name })));
    setProducts(allProducts);
  };

  const createProduct = async (e) => {
    e.preventDefault();
    try {
      await api.post('/products', { ...form, branch_id: 1 });
      setShowForm(false);
      setForm({ name: '', description: '', history: '', ingredients: '', price: '', cost: '', category_id: '', preparation_time_min: 15, image_url: '', model_3d_url: '', is_available: true });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error');
    }
  };

  const toggleAvailability = async (id, current) => {
    try {
      await api.put(`/products/${id}`, { is_available: !current });
      fetchData();
    } catch (err) {
      alert('Error al actualizar');
    }
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <h1 style={{ color: '#e2e8f0', fontSize: 28 }}>🍽️ Gestionar Menú</h1>
        <button onClick={() => setShowForm(!showForm)} className="btn btn-primary">
          {showForm ? 'Cancelar' : '+ Nuevo Plato'}
        </button>
      </div>

      {showForm && (
        <div className="card animate-fade-in" style={{ marginBottom: 24 }}>
          <h3 style={{ color: '#e2e8f0', marginBottom: 16 }}>Crear Producto</h3>
          <form onSubmit={createProduct} style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12 }}>
            <input type="text" placeholder="Nombre del plato *" className="input" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required />
            <select className="input" value={form.category_id} onChange={e => setForm({...form, category_id: e.target.value})} required>
              <option value="">Categoría *</option>
              {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <input type="number" step="0.01" placeholder="Precio *" className="input" value={form.price} onChange={e => setForm({...form, price: e.target.value})} required />
            <input type="number" step="0.01" placeholder="Costo" className="input" value={form.cost} onChange={e => setForm({...form, cost: e.target.value})} />
            <input type="number" placeholder="Tiempo prep. (min)" className="input" value={form.preparation_time_min} onChange={e => setForm({...form, preparation_time_min: e.target.value})} />
            <input type="text" placeholder="URL imagen" className="input" value={form.image_url} onChange={e => setForm({...form, image_url: e.target.value})} />
            <input type="text" placeholder="URL modelo 3D (AR)" className="input" value={form.model_3d_url} onChange={e => setForm({...form, model_3d_url: e.target.value})} />
            <textarea placeholder="Descripción" className="input" value={form.description} onChange={e => setForm({...form, description: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Historia del plato" className="input" value={form.history} onChange={e => setForm({...form, history: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Ingredientes" className="input" value={form.ingredients} onChange={e => setForm({...form, ingredients: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <button type="submit" className="btn btn-success" style={{ gridColumn: 'span 2' }}>Crear Plato</button>
          </form>
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
        {products.map(product => (
          <div key={product.id} className="card" style={{ position: 'relative' }}>
            <div style={{
              width: '100%', height: 150, borderRadius: 10,
              background: product.image_url ? `url(${product.image_url}) center/cover` : '#334155',
              marginBottom: 12, display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 40,
            }}>
              {!product.image_url && '🍽️'}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
              <h4 style={{ color: '#e2e8f0', fontSize: 15 }}>{product.name}</h4>
              <span style={{ color: '#fbbf24', fontWeight: 700 }}>${product.price?.toFixed(2)}</span>
            </div>
            <p style={{ color: '#94a3b8', fontSize: 12, marginBottom: 8 }}>{product.categoryName}</p>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <button
                onClick={() => toggleAvailability(product.id, product.is_available)}
                style={{
                  padding: '6px 12px', borderRadius: 8, border: 'none',
                  background: product.is_available ? 'rgba(16, 185, 129, 0.1)' : 'rgba(239, 68, 68, 0.1)',
                  color: product.is_available ? '#10b981' : '#ef4444',
                  fontSize: 12, fontWeight: 600, cursor: 'pointer',
                }}
              >
                {product.is_available ? '✓ Disponible' : '✗ No disponible'}
              </button>
              {product.model_3d_url && (
                <span style={{ color: '#38bdf8', fontSize: 11, fontWeight: 600 }}>🥽 AR</span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MenuPage;
